	let selected = 0;
	let custom = 0;
	for (const reaction of reactions.reactions) if (reaction._ === "reactionEmoji") {
		if (active.has(reaction.emoticon)) ++selected;
	} else if (reaction._ === "reactionCustomEmoji") ++custom;
	if (isBroadcast) return {
		type: "count",
		count: selected + custom + paid
	};
